0001 | static void *__bpf_ringbuf_reserve(struct bpf_ringbuf *rb, u64 size)
0002 | {
0003 | unsigned long cons_pos, prod_pos, new_prod_pos, flags;
0004 | u32 len, pg_off;
0005 | struct bpf_ringbuf_hdr *hdr;
0006 | if (unlikely(size > RINGBUF_MAX_RECORD_SZ))
0007 | return NULL;
0008 | len = round_up(size + BPF_RINGBUF_HDR_SZ, 8);
0009 | cons_pos = smp_load_acquire(&rb->consumer_pos);
0010 | if (in_nmi()) {
0011 | if (!spin_trylock_irqsave(&rb->spinlock, flags))
0012 | return NULL;
0013 | } else {
0014 | spin_lock_irqsave(&rb->spinlock, flags);
0015 | }
0016 | prod_pos = rb->producer_pos;
0017 | new_prod_pos = prod_pos + len;
0018 | if (new_prod_pos - cons_pos > rb->mask) {
0019 | spin_unlock_irqrestore(&rb->spinlock, flags);
0020 | return NULL;
0021 | }
0022 | hdr = (void *)rb->data + (prod_pos & rb->mask);
0023 | pg_off = bpf_ringbuf_rec_pg_off(rb, hdr);
0024 | hdr->len = size | BPF_RINGBUF_BUSY_BIT;
0025 | hdr->pg_off = pg_off;
0026 | smp_store_release(&rb->producer_pos, new_prod_pos);
0027 | spin_unlock_irqrestore(&rb->spinlock, flags);
0028 | return (void *)hdr + BPF_RINGBUF_HDR_SZ;
0029 | }

