0001 | static s32 gf_avc_read_sps_bs_internal(GF_BitStream *bs, AVCState *avc, u32 subseq_sps, u32 *vui_flag_pos, u32 nal_hdr)
0002 | {
0003 | AVC_SPS *sps;
0004 | s32 mb_width, mb_height, sps_id = -1;
0005 | u32 profile_idc, level_idc, pcomp, i, chroma_format_idc, cl = 0, cr = 0, ct = 0, cb = 0, luma_bd, chroma_bd;
0006 | u8 separate_colour_plane_flag = 0;
0007 | if (!vui_flag_pos) {
0008 | gf_bs_enable_emulation_byte_removal(bs, GF_TRUE);
0009 | }
0010 | if (!bs) {
0011 | return -1;
0012 | }
0013 | if (!nal_hdr) {
0014 | gf_bs_read_int_log(bs, 1, "forbidden_zero_bit");
0015 | gf_bs_read_int_log(bs, 2, "nal_ref_idc");
0016 | gf_bs_read_int_log(bs, 5, "nal_unit_type");
0017 | }
0018 | profile_idc = gf_bs_read_int_log(bs, 8, "profile_idc");
0019 | pcomp = gf_bs_read_int_log(bs, 8, "profile_compatibility");
0020 | if (pcomp & 0x3)
0021 | return -1;
0022 | level_idc = gf_bs_read_int_log(bs, 8, "level_idc");
0023 | sps_id = gf_bs_read_ue_log(bs, "sps_id") + GF_SVC_SSPS_ID_SHIFT * subseq_sps;
0024 | if (sps_id >= 32) {
0025 | return -1;
0026 | }
0027 | if (sps_id < 0) {
0028 | return -1;
0029 | }
0030 | luma_bd = chroma_bd = 0;
0031 | sps = &avc->sps[sps_id];
0032 | chroma_format_idc = sps->ChromaArrayType = 1;
0033 | sps->state |= subseq_sps ? AVC_SUBSPS_PARSED : AVC_SPS_PARSED;
0034 | switch (profile_idc) {
0035 | case 100:
0036 | case 110:
0037 | case 122:
0038 | case 244:
0039 | case 44:
0040 | if (pcomp & 0xE0)
0041 | return -1;
0042 | case 83:
0043 | case 86:
0044 | case 118:
0045 | case 128:
0046 | chroma_format_idc = gf_bs_read_ue_log(bs, "chroma_format_idc");
0047 | sps->ChromaArrayType = chroma_format_idc;
0048 | if (chroma_format_idc == 3) {
0049 | separate_colour_plane_flag = gf_bs_read_int_log(bs, 1, "separate_colour_plane_flag");
0050 | if (separate_colour_plane_flag) sps->ChromaArrayType = 0;
0051 | }
0052 | luma_bd = gf_bs_read_ue_log(bs, "luma_bit_depth");
0053 | chroma_bd = gf_bs_read_ue_log(bs, "chroma_bit_depth");
0054 | gf_bs_read_int_log(bs, 1, "qpprime_y_zero_transform_bypass_flag");
0055 | if (gf_bs_read_int_log(bs, 1, "seq_scaling_matrix_present_flag")) {
0056 | u32 k;
0057 | for (k = 0; k < 8; k++) {
0058 | if (gf_bs_read_int_log_idx(bs, 1, "seq_scaling_list_present_flag", k)) {
0059 | u32 z, last = 8, next = 8;
0060 | u32 sl = k < 6 ? 16 : 64;
0061 | for (z = 0; z < sl; z++) {
0062 | if (next) {
0063 | s32 delta = gf_bs_read_se(bs);
0064 | next = (last + delta + 256) % 256;
0065 | }
0066 | last = next ? next : last;
0067 | }
0068 | }
0069 | }
0070 | }
0071 | break;
0072 | }
0073 | sps->profile_idc = profile_idc;
0074 | sps->level_idc = level_idc;
0075 | sps->prof_compat = pcomp;
0076 | sps->log2_max_frame_num = gf_bs_read_ue_log(bs, "log2_max_frame_num") + 4;
0077 | sps->poc_type = gf_bs_read_ue_log(bs, "poc_type");
