0079 | sps->luma_bit_depth_m8 = luma_bd;
0080 | sps->chroma_bit_depth_m8 = chroma_bd;
0081 | if (sps->poc_type == 0) {
0082 | sps->log2_max_poc_lsb = gf_bs_read_ue_log(bs, "log2_max_poc_lsb") + 4;
0083 | }
0084 | else if (sps->poc_type == 1) {
