0098 | }
0099 | sps->max_num_ref_frames = gf_bs_read_ue_log(bs, "max_num_ref_frames");
0100 | sps->gaps_in_frame_num_value_allowed_flag = gf_bs_read_int_log(bs, 1, "gaps_in_frame_num_value_allowed_flag");
0101 | mb_width = gf_bs_read_ue_log(bs, "pic_width_in_mbs_minus1") + 1;
0102 | mb_height = gf_bs_read_ue_log(bs, "pic_height_in_map_units_minus1") + 1;
