0109 | int CropUnitX, CropUnitY, SubWidthC = -1, SubHeightC = -1;
0110 | if (chroma_format_idc == 1) {
0111 | SubWidthC = 2; SubHeightC = 2;
0112 | }
0113 | else if (chroma_format_idc == 2) {
0114 | SubWidthC = 2; SubHeightC = 1;
0115 | }
0116 | else if ((chroma_format_idc == 3) && (separate_colour_plane_flag == 0)) {
