0001 | void CommunicatorClass::ixfrSuck(const DNSName &domain, const TSIGTriplet& tt, const ComboAddress& laddr, const ComboAddress& remote, scoped_ptr<AuthLua>& pdl,
0002 | ZoneStatus& zs, vector<DNSRecord>* axfr)
0003 | {
0004 | UeberBackend B; 
0005 | DomainInfo di;
0006 | di.backend=0;
0007 | try {
0008 | DNSSECKeeper dk (&B); 
0009 | if(!B.getDomainInfo(domain, di) || !di.backend) {       L<<Logger::Error<<"Can't determine backend for domain '"<<domain<<"'"<<endl;
0010 | return;
0011 | }
0012 | soatimes st;
0013 | memset(&st, 0, sizeof(st));
0014 | st.serial=di.serial;
0015 | DNSRecord dr;
0016 | dr.d_content = std::make_shared<SOARecordContent>(DNSName("."), DNSName("."), st);
0017 | auto deltas = getIXFRDeltas(remote, domain, dr, tt, laddr.sin4.sin_family ? &laddr : 0);
0018 | zs.numDeltas=deltas.size();
0019 | for(const auto& d : deltas) {
0020 | const auto& remove = d.first;
0021 | const auto& add = d.second;
0022 | if(remove.empty()) {         *axfr = add;
0023 | return;
0024 | }
0025 | map<pair<DNSName,uint16_t>, pair<vector<DNSRecord>, vector<DNSRecord> > > grouped;
0026 | for(const auto& x: remove)
0027 | grouped[{x.d_name, x.d_type}].first.push_back(x);
0028 | for(const auto& x: add)
0029 | grouped[{x.d_name, x.d_type}].second.push_back(x);
0030 | di.backend->startTransaction(domain, -1);
0031 | for(const auto g : grouped) {
0032 | DNSResourceRecord rr;
0033 | vector<DNSRecord> rrset;
0034 | B.lookup(QType(g.first.second), g.first.first, 0, di.id);
0035 | while(B.get(rr)) {
0036 | rrset.push_back(DNSRecord{rr});
0037 | }
0038 | rrset.erase(remove_if(rrset.begin(), rrset.end(), 
0039 | [&g](const DNSRecord& dr) {
0040 | return count(g.second.first.cbegin(), 
0041 | g.second.first.cend(), dr);
0042 | }), rrset.end());
0043 | for(const auto& x : g.second.second) {
0044 | rrset.push_back(x);
0045 | }
0046 | vector<DNSResourceRecord> replacement;
0047 | for(const auto& x : rrset) {
0048 | DNSResourceRecord dr(x);
0049 | dr.qname += domain;
0050 | dr.domain_id = di.id;
0051 | if(x.d_type == QType::SOA) {
0052 | auto sr = getRR<SOARecordContent>(x);
0053 | zs.soa_serial=sr->d_st.serial;
0054 | }
0055 | replacement.push_back(dr);
0056 | }
0057 | di.backend->replaceRRSet(di.id, g.first.first+domain, QType(g.first.second), replacement);
0058 | }
0059 | di.backend->commitTransaction();
0060 | }
0061 | }
0062 | catch(std::exception& p) {
0063 | L<<Logger::Error<<"Got exception during IXFR: "<<p.what()<<endl;
0064 | throw;
0065 | }
0066 | catch(PDNSException& p) {
0067 | L<<Logger::Error<<"Got exception during IXFR: "<<p.reason<<endl;
0068 | throw;
0069 | }  
0070 | }

