0001 | static void intel_hda_response(HDACodecDevice *dev, bool solicited, uint32_t response)
0002 | {
0003 | const MemTxAttrs attrs = MEMTXATTRS_UNSPECIFIED;
0004 | HDACodecBus *bus = HDA_BUS(dev->qdev.parent_bus);
0005 | IntelHDAState *d = container_of(bus, IntelHDAState, codecs);
0006 | hwaddr addr;
0007 | uint32_t wp, ex;
0008 | MemTxResult res = MEMTX_OK;
0009 | if (d->ics & ICH6_IRS_BUSY) {
0010 | dprint(d, 2, "%s: [irr] response 0x%x, cad 0x%x\n",
0011 | __func__, response, dev->cad);
0012 | d->irr = response;
0013 | d->ics &= ~(ICH6_IRS_BUSY | 0xf0);
0014 | d->ics |= (ICH6_IRS_VALID | (dev->cad << 4));
0015 | return;
0016 | }
0017 | if (!(d->rirb_ctl & ICH6_RBCTL_DMA_EN)) {
0018 | dprint(d, 1, "%s: rirb dma disabled, drop codec response\n", __func__);
0019 | return;
0020 | }
0021 | ex = (solicited ? 0 : (1 << 4)) | dev->cad;
0022 | wp = (d->rirb_wp + 1) & 0xff;
0023 | addr = intel_hda_addr(d->rirb_lbase, d->rirb_ubase);
0024 | res |= stl_le_pci_dma(&d->pci, addr + 8 * wp, response, attrs);
0025 | res |= stl_le_pci_dma(&d->pci, addr + 8 * wp + 4, ex, attrs);
0026 | if (res != MEMTX_OK && (d->rirb_ctl & ICH6_RBCTL_OVERRUN_EN)) {
0027 | d->rirb_sts |= ICH6_RBSTS_OVERRUN;
0028 | intel_hda_update_irq(d);
0029 | }
0030 | d->rirb_wp = wp;
0031 | dprint(d, 2, "%s: [wp 0x%x] response 0x%x, extra 0x%x\n",
0032 | __func__, wp, response, ex);
0033 | d->rirb_count++;
0034 | if (d->rirb_count == d->rirb_cnt) {
0035 | dprint(d, 2, "%s: rirb count reached (%d)\n", __func__, d->rirb_count);
0036 | if (d->rirb_ctl & ICH6_RBCTL_IRQ_EN) {
0037 | d->rirb_sts |= ICH6_RBSTS_IRQ;
0038 | intel_hda_update_irq(d);
0039 | }
0040 | } else if ((d->corb_rp & 0xff) == d->corb_wp) {
0041 | dprint(d, 2, "%s: corb ring empty (%d/%d)\n", __func__,
0042 | d->rirb_count, d->rirb_cnt);
0043 | if (d->rirb_ctl & ICH6_RBCTL_IRQ_EN) {
0044 | d->rirb_sts |= ICH6_RBSTS_IRQ;
0045 | intel_hda_update_irq(d);
0046 | }
0047 | }
0048 | }

