0008 | uint8_t opt_left = (offset - TCP_HDR_OFFSET_MIN) * 4;
0009 | while (opt_left > 0) {
0010 | tcp_hdr_opt_t *option = (tcp_hdr_opt_t *) opt_ptr;
0011 | switch (option->kind) {
0012 | case TCP_OPTION_KIND_EOL:
0013 | DEBUG("gnrc_tcp_option.c : _option_parse() : EOL option found\n");
0014 | return 0;
0015 | case TCP_OPTION_KIND_NOP:
0016 | DEBUG("gnrc_tcp_option.c : _option_parse() : NOP option found\n");
0017 | opt_ptr += 1;
0018 | opt_left -= 1;
0019 | continue;
0020 | case TCP_OPTION_KIND_MSS:
0021 | if (option->length != TCP_OPTION_LENGTH_MSS) {
0022 | DEBUG("gnrc_tcp_option.c : _option_parse() : invalid MSS Option length.\n");
0023 | return -1;
0024 | }
0025 | tcb->mss = (option->value[0] << 8) | option->value[1];
0026 | DEBUG("gnrc_tcp_option.c : _option_parse() : MSS option found. MSS=%"PRIu16"\n",
0027 | tcb->mss);
0028 | break;
0029 | default:
0030 | DEBUG("gnrc_tcp_option.c : _option_parse() : Unknown option found.\
0031 | KIND=%"PRIu8", LENGTH=%"PRIu8"\n", option->kind, option->length);
0032 | }
0033 | if (option->length > opt_left) {
0034 | DEBUG("gnrc_tcp_option.c : _option_parse() : invalid option length\n");
0035 | return 0;
0036 | }
0037 | opt_ptr += option->length;
0038 | opt_left -= option->length;
0039 | }
0040 | return 0;
0041 | }

