0001 | void CalculateOutputIndexValueRowID(
0002 | const RowPartitionTensor& value_rowids,
0003 | const vector<INDEX_TYPE>& parent_output_index,
0004 | INDEX_TYPE output_index_multiplier, INDEX_TYPE output_size,
0005 | vector<INDEX_TYPE>* result) {
0006 | const INDEX_TYPE index_size = value_rowids.size();
0007 | result->reserve(index_size);
0008 | if (index_size == 0) {
0009 | return;
0010 | }
0011 | INDEX_TYPE current_output_column = 0;
0012 | INDEX_TYPE current_value_rowid = value_rowids(0);
0013 | DCHECK_LT(current_value_rowid, parent_output_index.size());
0014 | INDEX_TYPE current_output_index = parent_output_index[current_value_rowid];
0015 | result->push_back(current_output_index);
0016 | for (INDEX_TYPE i = 1; i < index_size; ++i) {
0017 | INDEX_TYPE next_value_rowid = value_rowids(i);
0018 | if (next_value_rowid == current_value_rowid) {
0019 | if (current_output_index >= 0) {
0020 | ++current_output_column;
0021 | if (current_output_column < output_size) {
0022 | current_output_index += output_index_multiplier;
0023 | } else {
0024 | current_output_index = -1;
0025 | }
0026 | }
0027 | } else {
0028 | current_output_column = 0;
0029 | current_value_rowid = next_value_rowid;
0030 | DCHECK_LT(next_value_rowid, parent_output_index.size());
0031 | current_output_index = parent_output_index[next_value_rowid];
0032 | }
0033 | result->push_back(current_output_index);
0034 | }
0035 | DCHECK_EQ(result->size(), value_rowids.size());
0036 | }

