0001 | int WavpackVerifySingleBlock (unsigned char *buffer, int verify_checksum)
0002 | {
0003 | WavpackHeader *wphdr = (WavpackHeader *) buffer;
0004 | uint32_t checksum_passed = 0, bcount, meta_bc;
0005 | unsigned char *dp, meta_id, c1, c2;
0006 | if (strncmp (wphdr->ckID, "wvpk", 4) || wphdr->ckSize + 8 < sizeof (WavpackHeader))
0007 | return FALSE;
0008 | bcount = wphdr->ckSize - sizeof (WavpackHeader) + 8;
0009 | dp = (unsigned char *)(wphdr + 1);
0010 | while (bcount >= 2) {
0011 | meta_id = *dp++;
0012 | c1 = *dp++;
0013 | meta_bc = c1 << 1;
0014 | bcount -= 2;
0015 | if (meta_id & ID_LARGE) {
0016 | if (bcount < 2)
0017 | return FALSE;
0018 | c1 = *dp++;
0019 | c2 = *dp++;
0020 | meta_bc += ((uint32_t) c1 << 9) + ((uint32_t) c2 << 17);
0021 | bcount -= 2;
0022 | }
0023 | if (bcount < meta_bc)
0024 | return FALSE;
0025 | if (verify_checksum && (meta_id & ID_UNIQUE) == ID_BLOCK_CHECKSUM) {
0026 | #ifdef BITSTREAM_SHORTS
0027 | uint16_t *csptr = (uint16_t*) buffer;
0028 | #else
0029 | unsigned char *csptr = buffer;
0030 | #endif
0031 | int wcount = (int)(dp - 2 - buffer) >> 1;
0032 | uint32_t csum = (uint32_t) -1;
0033 | if ((meta_id & ID_ODD_SIZE) || meta_bc < 2 || meta_bc > 4)
0034 | return FALSE;
0035 | #ifdef BITSTREAM_SHORTS
0036 | while (wcount--)
0037 | csum = (csum * 3) + *csptr++;
0038 | #else
0039 | WavpackNativeToLittleEndian ((WavpackHeader *) buffer, WavpackHeaderFormat);
0040 | while (wcount--) {
0041 | csum = (csum * 3) + csptr [0] + (csptr [1] << 8);
0042 | csptr += 2;
0043 | }
0044 | WavpackLittleEndianToNative ((WavpackHeader *) buffer, WavpackHeaderFormat);
0045 | #endif
0046 | if (meta_bc == 4) {
0047 | if (*dp++ != (csum & 0xff) || *dp++ != ((csum >> 8) & 0xff) || *dp++ != ((csum >> 16) & 0xff) || *dp++ != ((csum >> 24) & 0xff))
0048 | return FALSE;
0049 | }
0050 | else {
0051 | csum ^= csum >> 16;
0052 | if (*dp++ != (csum & 0xff) || *dp++ != ((csum >> 8) & 0xff))
0053 | return FALSE;
0054 | }
0055 | checksum_passed++;
0056 | }
0057 | bcount -= meta_bc;
0058 | dp += meta_bc;
0059 | }
0060 | return (bcount == 0) && (!verify_checksum || !(wphdr->flags & HAS_CHECKSUM) || checksum_passed);
0061 | }

