0001 | static MagickBooleanType IsWEBPImageLossless(const unsigned char *stream,
0002 | const size_t length)
0003 | {
0004 | #define VP8_CHUNK_INDEX  15
0005 | #define LOSSLESS_FLAG  'L'
0006 | #define EXTENDED_HEADER  'X'
0007 | #define VP8_CHUNK_HEADER  "VP8"
0008 | #define VP8_CHUNK_HEADER_SIZE  3
0009 | #define RIFF_HEADER_SIZE  12
0010 | #define VP8X_CHUNK_SIZE  10
0011 | #define TAG_SIZE  4
0012 | #define CHUNK_SIZE_BYTES  4
0013 | #define CHUNK_HEADER_SIZE  8
0014 | #define MAX_CHUNK_PAYLOAD  (~0U-CHUNK_HEADER_SIZE-1)
0015 | ssize_t
0016 | offset;
0017 | if (stream[VP8_CHUNK_INDEX] != EXTENDED_HEADER)
0018 | return(stream[VP8_CHUNK_INDEX] == LOSSLESS_FLAG ? MagickTrue : MagickFalse);
0019 | offset=RIFF_HEADER_SIZE+TAG_SIZE+CHUNK_SIZE_BYTES+VP8X_CHUNK_SIZE;
0020 | while (offset <= (ssize_t) length)
0021 | {
0022 | uint32_t
0023 | chunk_size,
0024 | chunk_size_pad;
0025 | chunk_size=ReadWebPLSBWord(stream+offset+TAG_SIZE);
0026 | if (chunk_size > MAX_CHUNK_PAYLOAD)
0027 | break;
0028 | chunk_size_pad=(CHUNK_HEADER_SIZE+chunk_size+1) & ~1;
0029 | if (memcmp(stream+offset,VP8_CHUNK_HEADER,VP8_CHUNK_HEADER_SIZE) == 0)
0030 | return(*(stream+offset+VP8_CHUNK_HEADER_SIZE) == LOSSLESS_FLAG ?
0031 | MagickTrue : MagickFalse);
0032 | offset+=chunk_size_pad;
0033 | }
0034 | return(MagickFalse);
0035 | }

