0011 | if ( cur >= limit )
0012 | {
0013 | FT_ERROR(( "t42_parse_encoding: out of bounds\n" ));
0014 | parser->root.error = FT_THROW( Invalid_File_Format );
0015 | return;
0016 | }
0017 | if ( ft_isdigit( *cur ) || *cur == '[' )
0018 | {
0019 | T1_Encoding  encode          = &face->type1.encoding;
0020 | FT_UInt      count, n;
0021 | PS_Table     char_table      = &loader->encoding_table;
0022 | FT_Memory    memory          = parser->root.memory;
0023 | FT_Error     error;
0024 | FT_Bool      only_immediates = 0;
0025 | if ( *cur == '[' )
0026 | {
0027 | count           = 256;
0028 | only_immediates = 1;
0029 | parser->root.cursor++;
0030 | }
0031 | else
0032 | count = (FT_UInt)T1_ToInt( parser );
0033 | T1_Skip_Spaces( parser );
0034 | if ( parser->root.cursor >= limit )
0035 | return;
0036 | loader->num_chars = encode->num_chars = count;
0037 | if ( FT_NEW_ARRAY( encode->char_index, count )     ||
0038 | FT_NEW_ARRAY( encode->char_name,  count )     ||
0039 | FT_SET_ERROR( psaux->ps_table_funcs->init(
0040 | char_table, count, memory ) ) )
0041 | {
0042 | parser->root.error = error;
0043 | return;
0044 | }
0045 | for ( n = 0; n < count; n++ )
0046 | {
0047 | char*  notdef = (char *)".notdef";
0048 | T1_Add_Table( char_table, n, notdef, 8 );
0049 | }
0050 | n = 0;
0051 | T1_Skip_Spaces( parser );
0052 | while ( parser->root.cursor < limit )
0053 | {
0054 | cur = parser->root.cursor;
0055 | if ( *cur == 'd' && cur + 3 < limit )
0056 | {
0057 | if ( cur[1] == 'e'          &&
0058 | cur[2] == 'f'          &&
0059 | t42_is_space( cur[3] ) )
0060 | {
0061 | FT_TRACE6(( "encoding end\n" ));
0062 | cur += 3;
0063 | break;
0064 | }
0065 | }
0066 | if ( *cur == ']' )
0067 | {
0068 | FT_TRACE6(( "encoding end\n" ));
0069 | cur++;
0070 | break;
0071 | }
0072 | if ( ft_isdigit( *cur ) || only_immediates )
0073 | {
0074 | FT_Int  charcode;
0075 | if ( only_immediates )
0076 | charcode = n;
0077 | else
0078 | {
0079 | charcode = (FT_Int)T1_ToInt( parser );
0080 | T1_Skip_Spaces( parser );
0081 | }
0082 | cur = parser->root.cursor;
0083 | if ( *cur == '/' && cur + 2 < limit && n < count )
0084 | {
0085 | FT_PtrDist  len;
0086 | cur++;
0087 | parser->root.cursor = cur;
0088 | T1_Skip_PS_Token( parser );
0089 | if ( parser->root.error )
0090 | return;
0091 | len = parser->root.cursor - cur;
0092 | parser->root.error = T1_Add_Table( char_table, charcode,
0093 | cur, len + 1 );
0094 | if ( parser->root.error )
0095 | return;
0096 | char_table->elements[charcode][len] = '\0';
0097 | n++;
0098 | }
0099 | }
0100 | else
0101 | {
0102 | T1_Skip_PS_Token( parser );
0103 | if ( parser->root.error )
0104 | return;
0105 | }
0106 | T1_Skip_Spaces( parser );
0107 | }
0108 | face->type1.encoding_type  = T1_ENCODING_TYPE_ARRAY;
0109 | parser->root.cursor        = cur;
0110 | }
0111 | else
0112 | {
0113 | if ( cur + 17 < limit                                            &&
0114 | ft_strncmp( (const char*)cur, "StandardEncoding", 16 ) == 0 )
0115 | face->type1.encoding_type = T1_ENCODING_TYPE_STANDARD;
0116 | else if ( cur + 15 < limit                                          &&
0117 | ft_strncmp( (const char*)cur, "ExpertEncoding", 14 ) == 0 )
0118 | face->type1.encoding_type = T1_ENCODING_TYPE_EXPERT;
0119 | else if ( cur + 18 < limit                                             &&
0120 | ft_strncmp( (const char*)cur, "ISOLatin1Encoding", 17 ) == 0 )
0121 | face->type1.encoding_type = T1_ENCODING_TYPE_ISOLATIN1;
0122 | else
0123 | {
0124 | FT_ERROR(( "t42_parse_encoding: invalid token\n" ));
0125 | parser->root.error = FT_THROW( Invalid_File_Format );
0126 | }
0127 | }
0128 | }

