0001 | TEE_Result TEE_CipherUpdate(TEE_OperationHandle operation, const void *srcData,
0002 | uint32_t srcLen, void *destData, uint32_t *destLen)
0003 | {
0004 | TEE_Result res;
0005 | size_t req_dlen;
0006 | uint64_t dl;
