0011 | res = TEE_ERROR_BAD_PARAMETERS;
0012 | goto out;
0013 | }
0014 | if (operation->info.operationClass != TEE_OPERATION_CIPHER) {
0015 | res = TEE_ERROR_BAD_PARAMETERS;
0016 | goto out;
0017 | }
0018 | if ((operation->info.handleState & TEE_HANDLE_FLAG_INITIALIZED) == 0) {
0019 | res = TEE_ERROR_BAD_PARAMETERS;
0020 | goto out;
0021 | }
0022 | if (operation->operationState != TEE_OPERATION_STATE_ACTIVE) {
0023 | res = TEE_ERROR_BAD_PARAMETERS;
0024 | goto out;
0025 | }
0026 | if (!srcData && !srcLen) {
0027 | *destLen = 0;
0028 | res = TEE_SUCCESS;
0029 | goto out;
0030 | }
0031 | if (operation->block_size > 1) {
0032 | req_dlen = ((operation->buffer_offs + srcLen) /
0033 | operation->block_size) * operation->block_size;
0034 | } else {
0035 | req_dlen = srcLen;
0036 | }
0037 | if (operation->buffer_two_blocks) {
0038 | if (req_dlen > operation->block_size * 2)
0039 | req_dlen -= operation->block_size * 2;
0040 | else
0041 | req_dlen = 0;
0042 | }
0043 | if (*destLen < req_dlen) {
0044 | *destLen = req_dlen;
0045 | res = TEE_ERROR_SHORT_BUFFER;
0046 | goto out;
0047 | }
0048 | dl = *destLen;
0049 | if (operation->block_size > 1) {
0050 | res = tee_buffer_update(operation, utee_cipher_update, srcData,
0051 | srcLen, destData, &dl);
0052 | } else {
