0009 | pSendMessage->Release();
0010 | return -k_EResultLimitExceeded; 
0011 | }
0012 | if ( cbData > k_cbMaxUnreliableMsgSize && !( pSendMessage->m_nFlags & k_nSteamNetworkingSend_Reliable )  )
0013 | {
0014 | SpewWarningRateLimited( usecNow, "Trying to send a very large (%d bytes) unreliable message.  Sending as reliable instead.\n", cbData );
0015 | pSendMessage->m_nFlags |= k_nSteamNetworkingSend_Reliable;
0016 | }
0017 | if ( pSendMessage->m_nFlags & k_nSteamNetworkingSend_NoDelay )
0018 | {
0019 | }
