0023 | if ( pSendMessage->m_nFlags & k_nSteamNetworkingSend_Reliable )
0024 | {
0025 | pSendMessage->SNPSend_SetReliableStreamPos( m_senderState.m_nReliableStreamPos );
0026 | byte *hdr = pSendMessage->SNPSend_ReliableHeader();
0027 | hdr[0] = 0;
