0029 | int64 nMsgNumGap = pSendMessage->m_nMessageNumber - m_senderState.m_nLastSendMsgNumReliable;
0030 | Assert( nMsgNumGap >= 1 );
0031 | if ( nMsgNumGap > 1 )
0032 | {
0033 | hdrEnd = SerializeVarInt( hdrEnd, (uint64)nMsgNumGap );
0034 | hdr[0] |= 0x40;
0035 | }
0036 | if ( cbData < 0x20 )
0037 | {
0038 | hdr[0] |= (byte)cbData;
0039 | }
0040 | else
0041 | {
0042 | hdr[0] |= (byte)( 0x20 | ( cbData & 0x1f ) );
0043 | hdrEnd = SerializeVarInt( hdrEnd, cbData>>5U );
0044 | }
0045 | pSendMessage->m_cbSNPSendReliableHeader = hdrEnd - hdr;
0046 | pSendMessage->m_cbSize += pSendMessage->m_cbSNPSendReliableHeader;
0047 | m_senderState.m_nReliableStreamPos += pSendMessage->m_cbSize;
0048 | ++m_senderState.m_nMessagesSentReliable;
0049 | m_senderState.m_cbPendingReliable += pSendMessage->m_cbSize;
0050 | m_senderState.m_nLastSendMsgNumReliable = pSendMessage->m_nMessageNumber;
0051 | Assert( pSendMessage->SNPSend_IsReliable() );
0052 | }
0053 | else
0054 | {
0055 | pSendMessage->SNPSend_SetReliableStreamPos( 0 );
0056 | pSendMessage->m_cbSNPSendReliableHeader = 0;
0057 | ++m_senderState.m_nMessagesSentUnreliable;
0058 | m_senderState.m_cbPendingUnreliable += pSendMessage->m_cbSize;
0059 | Assert( !pSendMessage->SNPSend_IsReliable() );
0060 | }
0061 | m_senderState.m_messagesQueued.push_back( pSendMessage );
0062 | SpewVerboseGroup( m_connectionConfig.m_LogLevel_Message.Get(), "[%s] SendMessage %s: MsgNum=%lld sz=%d\n",
0063 | GetDescription(),
0064 | pSendMessage->SNPSend_IsReliable() ? "RELIABLE" : "UNRELIABLE",
0065 | (long long)pSendMessage->m_nMessageNumber,
0066 | pSendMessage->m_cbSize );
0067 | pSendMessage->SNPSend_SetUsecNagle( usecNow + m_connectionConfig.m_NagleTime.Get() );
0068 | if ( pSendMessage->m_nFlags & k_nSteamNetworkingSend_NoNagle )
0069 | m_senderState.ClearNagleTimers();
0070 | int64 result = pSendMessage->m_nMessageNumber;
0071 | if ( GetState() == k_ESteamNetworkingConnectionState_Connected )
0072 | {
0073 | SteamNetworkingMicroseconds usecNextThink = SNP_GetNextThinkTime( usecNow );
0074 | if ( usecNextThink > usecNow )
0075 | {
0076 | if ( m_senderState.m_messagesQueued.m_pFirst->SNPSend_UsecNagle() == 0 )
0077 | {
0078 | SpewVerbose( "[%s] RATELIM QueueTime is %.1fms, SendRate=%.1fk, BytesQueued=%d\n", 
0079 | GetDescription(),
0080 | m_senderState.CalcTimeUntilNextSend() * 1e-3,
0081 | m_senderState.m_n_x * ( 1.0/1024.0),
0082 | m_senderState.PendingBytesTotal()
0083 | );
0084 | }
0085 | EnsureMinThinkTime( usecNextThink );
0086 | }
0087 | else
0088 | {
0089 | if ( pSendMessage->m_nFlags & k_nSteamNetworkingSend_UseCurrentThread )
0090 | {
0091 | if ( pbThinkImmediately )
0092 | {
0093 | *pbThinkImmediately = true;
0094 | }
0095 | else
0096 | {
0097 | CheckConnectionStateAndSetNextThinkTime( usecNow );
0098 | }
0099 | }
0100 | else
0101 | {
0102 | SetNextThinkTimeASAP();
0103 | }
0104 | }
0105 | }
