0006 | #define GET32(x) do { if (j + 4 > length) goto err; memcpy(&t32_, packet + j, 4); j += 4; x = ntohl(t32_); } while (0)
0007 | #define GET16(x) do { if (j + 2 > length) goto err; memcpy(&t_, packet + j, 2); j += 2; x = ntohs(t_); } while (0)
0008 | #define GET8(x) do { if (j >= length) goto err; x = packet[j++]; } while (0)
0009 | char *cp = name_out;
0010 | const char *const end = name_out + name_out_len;
