0012 | u8 label_len;
0013 | if (j >= length) return -1;
0014 | GET8(label_len);
0015 | if (!label_len) break;
0016 | if (label_len & 0xc0) {
0017 | u8 ptr_low;
0018 | GET8(ptr_low);
0019 | if (name_end < 0) name_end = j;
0020 | j = (((int)label_len & 0x3f) << 8) + ptr_low;
0021 | if (j < 0 || j >= length) return -1;
0022 | if (++ptr_count > length) return -1;
0023 | continue;
0024 | }
0025 | if (label_len > 63) return -1;
0026 | if (cp != name_out) {
0027 | if (cp + 1 >= end) return -1;
0028 | *cp++ = '.';
0029 | }
0030 | if (cp + label_len >= end) return -1;
0031 | memcpy(cp, packet + j, label_len);
0032 | cp += label_len;
0033 | j += label_len;
0034 | }
0035 | if (cp >= end) return -1;
0036 | *cp = '\0';
0037 | if (name_end < 0)
0038 | *idx = j;
0039 | else
0040 | *idx = name_end;
0041 | return 0;
0042 | err:
0043 | return -1;
0044 | }

