0150 | newserv->usn = malloc(l + 1);
0151 | if(!newserv->usn) {
0152 | syslog(LOG_ERR, "cannot allocate memory");
0153 | goto error;
0154 | }
0155 | memcpy(newserv->usn, p, l);
0156 | newserv->usn[l] = '\0';
0157 | p += l;
0158 | DECODELENGTH_CHECKLIMIT(l, p, buf + n);
0159 | if(p+l > buf+n) {
