commit_msg:
f2fs: fix a panic caused by NULL flush_cmd_control

Mount fs with option noflush_merge, boot failed for illegal address
fcc in function f2fs_issue_flush:

        if (!test_opt(sbi, FLUSH_MERGE)) {
                ret = submit_flush_wait(sbi);
                atomic_inc(&fcc->issued_flush);   ->  Here, fcc illegal
                return ret;
        }

Signed-off-by: Yunlei He <heyunlei@huawei.com>
Signed-off-by: Jaegeuk Kim <jaegeuk@kernel.org>

func:
[create_flush_cmd_control]

0001 | int create_flush_cmd_control(struct f2fs_sb_info *sbi)
0002 | {
0003 | dev_t dev = sbi->sb->s_bdev->bd_dev;
0004 | struct flush_cmd_control *fcc;
0005 | int err = 0;
0006 | if (SM_I(sbi)->fcc_info) {
0007 | fcc = SM_I(sbi)->fcc_info;
0008 | goto init_thread;
0009 | }
0010 | fcc = kzalloc(sizeof(struct flush_cmd_control), GFP_KERNEL);
0011 | if (!fcc)
0012 | return -ENOMEM;
0013 | atomic_set(&fcc->issued_flush, 0);
0014 | atomic_set(&fcc->issing_flush, 0);
0015 | init_waitqueue_head(&fcc->flush_wait_queue);
0016 | init_llist_head(&fcc->issue_list);
0017 | SM_I(sbi)->fcc_info = fcc;
0018 | init_thread:
