0001 | static int
0002 | init_traditional_PKWARE_decryption(struct archive_read *a)
0003 | {
0004 | struct zip *zip = (struct zip *)(a->format->data);
0005 | const void *p;
0006 | int retry;
0007 | int r;
0008 | if (zip->tctx_valid)
0009 | return (ARCHIVE_OK);
0010 | #define ENC_HEADER_SIZE12
0011 | p = __archive_read_ahead(a, ENC_HEADER_SIZE, NULL);
0012 | if (p == NULL) {
0013 | archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
0014 | "Truncated ZIP file data");
0015 | return (ARCHIVE_FATAL);
0016 | }
0017 | for (retry = 0;; retry++) {
0018 | const char *passphrase;
0019 | uint8_t crcchk;
0020 | passphrase = __archive_read_next_passphrase(a);
0021 | if (passphrase == NULL) {
0022 | archive_set_error(&a->archive, ARCHIVE_ERRNO_MISC,
0023 | (retry > 0)?
0024 | "Incorrect passphrase":
0025 | "Passphrase required for this entry");
0026 | return (ARCHIVE_FAILED);
0027 | }
0028 | r = trad_enc_init(&zip->tctx, passphrase, strlen(passphrase),
0029 | p, ENC_HEADER_SIZE, &crcchk);
0030 | if (r == 0 && crcchk == zip->entry->decdat)
0031 | break;
0032 | if (retry > 10000) {
0033 | archive_set_error(&a->archive, ARCHIVE_ERRNO_MISC,
0034 | "Too many incorrect passphrases");
0035 | return (ARCHIVE_FAILED);
0036 | }
0037 | }
0038 | __archive_read_consume(a, ENC_HEADER_SIZE);
0039 | zip->tctx_valid = 1;
0040 | zip->entry_bytes_remaining -= ENC_HEADER_SIZE;
0041 | zip->entry_compressed_bytes_read += ENC_HEADER_SIZE;
0042 | zip->decrypted_bytes_remaining = 0;
0043 | return (zip_alloc_decryption_buffer(a));
0044 | #undef ENC_HEADER_SIZE
0045 | }

