0001 | void Display::startAuth(const QString &user, const QString &password, const Session &session) {
0002 | m_passPhrase = password;
0003 | if (!session.isValid()) {
0004 | qCritical() << "Invalid session" << session.fileName();
0005 | return;
0006 | }
0007 | if (session.xdgSessionType().isEmpty()) {
0008 | qCritical() << "Failed to find XDG session type for session" << session.fileName();
0009 | return;
0010 | }
0011 | if (session.exec().isEmpty()) {
0012 | qCritical() << "Failed to find command for session" << session.fileName();
0013 | return;
0014 | }
0015 | QString existingSessionId;
0016 | if (Logind::isAvailable() && mainConfig.Users.ReuseSession.get()) {
0017 | OrgFreedesktopLogin1ManagerInterface manager(Logind::serviceName(), Logind::managerPath(), QDBusConnection::systemBus());
