0023 | if (session.service() == QLatin1String("sddm")) {
0024 | existingSessionId =  s.sessionId;
0025 | break;
0026 | }
0027 | }
0028 | }
0029 | }
0030 | m_lastSession = session;
0031 | m_sessionName = session.fileName();
0032 | qDebug() << "Session" << m_sessionName << "selected, command:" << session.exec();
0033 | int vt = terminalId();
0034 | if (session.xdgSessionType() == QLatin1String("wayland"))
0035 | vt = VirtualTerminal::setUpNewVt();
0036 | m_lastSession.setVt(vt);
0037 | QProcessEnvironment env;
0038 | env.insert(QStringLiteral("PATH"), mainConfig.Users.DefaultPath.get());
0039 | if (session.xdgSessionType() == QLatin1String("x11"))
0040 | env.insert(QStringLiteral("DISPLAY"), name());
0041 | env.insert(QStringLiteral("XDG_SEAT_PATH"), daemonApp->displayManager()->seatPath(seat()->name()));
0042 | env.insert(QStringLiteral("XDG_SESSION_PATH"), daemonApp->displayManager()->sessionPath(QStringLiteral("Session%1").arg(daemonApp->newSessionId())));
0043 | env.insert(QStringLiteral("DESKTOP_SESSION"), session.desktopSession());
0044 | env.insert(QStringLiteral("XDG_CURRENT_DESKTOP"), session.desktopNames());
0045 | env.insert(QStringLiteral("XDG_SESSION_CLASS"), QStringLiteral("user"));
0046 | env.insert(QStringLiteral("XDG_SESSION_TYPE"), session.xdgSessionType());
0047 | env.insert(QStringLiteral("XDG_SEAT"), seat()->name());
0048 | env.insert(QStringLiteral("XDG_SESSION_DESKTOP"), session.desktopNames());
0049 | if (seat()->name() == QLatin1String("seat0")) {
0050 | env.insert(QStringLiteral("XDG_VTNR"), QString::number(vt));
0051 | }
0052 | m_auth->insertEnvironment(env);
0053 | m_auth->setUser(user);
0054 | if (existingSessionId.isNull()) {
0055 | m_auth->setSession(session.exec());
0056 | } else {
0057 | connect(m_auth, &Auth::authentication, this, [=](){
0058 | qDebug() << "activating existing seat";
0059 | OrgFreedesktopLogin1ManagerInterface manager(Logind::serviceName(), Logind::managerPath(), QDBusConnection::systemBus());
0060 | manager.UnlockSession(existingSessionId);
0061 | manager.ActivateSession(existingSessionId);
0062 | });
0063 | }
0064 | m_auth->start();
0065 | }

