0032 | if (trb->dwTrb3 & XHCI_TRB_3_TC_BIT)
0033 | ccs ^= XHCI_CRCR_LO_RCS;
0034 | break;
0035 | case XHCI_TRB_TYPE_ENABLE_SLOT:
0036 | cmderr = pci_xhci_cmd_enable_slot(xdev, &slot);
0037 | break;
0038 | case XHCI_TRB_TYPE_DISABLE_SLOT:
0039 | XHCI_GET_SLOT(xdev, trb, slot, cmderr);
0040 | if (slot)
0041 | cmderr = pci_xhci_cmd_disable_slot(xdev, slot);
0042 | break;
0043 | case XHCI_TRB_TYPE_ADDRESS_DEVICE:
