0050 | if (slot)
0051 | cmderr = pci_xhci_cmd_config_ep(xdev, slot, trb);
0052 | break;
0053 | case XHCI_TRB_TYPE_EVALUATE_CTX:
0054 | XHCI_GET_SLOT(xdev, trb, slot, cmderr);
0055 | if (slot)
0056 | cmderr = pci_xhci_cmd_eval_ctx(xdev, slot, trb);
0057 | break;
0058 | case XHCI_TRB_TYPE_RESET_EP:
0059 | UPRINTF(LDBG, "Reset Endpoint on slot %d\r\n", slot);
0060 | XHCI_GET_SLOT(xdev, trb, slot, cmderr);
0061 | if (slot)
0062 | cmderr = pci_xhci_cmd_reset_ep(xdev, slot, trb);
0063 | break;
0064 | case XHCI_TRB_TYPE_STOP_EP:
0065 | UPRINTF(LDBG, "Stop Endpoint on slot %d\r\n", slot);
0066 | XHCI_GET_SLOT(xdev, trb, slot, cmderr);
0067 | if (slot)
0068 | cmderr = pci_xhci_cmd_reset_ep(xdev, slot, trb);
0069 | break;
0070 | case XHCI_TRB_TYPE_SET_TR_DEQUEUE:
0071 | XHCI_GET_SLOT(xdev, trb, slot, cmderr);
0072 | if (slot)
0073 | cmderr = pci_xhci_cmd_set_tr(xdev, slot, trb);
0074 | break;
0075 | case XHCI_TRB_TYPE_RESET_DEVICE:
0076 | XHCI_GET_SLOT(xdev, trb, slot, cmderr);
0077 | if (slot)
0078 | cmderr = pci_xhci_cmd_reset_device(xdev, slot);
0079 | break;
0080 | case XHCI_TRB_TYPE_FORCE_EVENT:
0081 | break;
0082 | case XHCI_TRB_TYPE_NEGOTIATE_BW:
0083 | break;
0084 | case XHCI_TRB_TYPE_SET_LATENCY_TOL:
0085 | break;
0086 | case XHCI_TRB_TYPE_GET_PORT_BW:
0087 | break;
0088 | case XHCI_TRB_TYPE_FORCE_HEADER:
0089 | break;
0090 | case XHCI_TRB_TYPE_NOOP_CMD:
0091 | break;
0092 | default:
0093 | UPRINTF(LDBG, "unsupported cmd %x\r\n", type);
0094 | break;
0095 | }
