0107 | trb = pci_xhci_trb_next(xdev, trb, &crcr);
0108 | if (!trb) {
0109 | UPRINTF(LDBG, "Get the invalid trb in %s!\r\n", __func__);
0110 | break;
0111 | }
0112 | }
