0014 | if( pInitPoly->mpFlagAry )
0015 | memcpy( mpFlagAry + nPos, pInitPoly->mpFlagAry, nSpace );
0016 | }
0017 | }
0018 | else
0019 | {
0020 | const sal_uInt16    nSecPos = nPos + nSpace;
