0026 | else
0027 | memset( pNewAry + nPos, 0, nSpaceSize );
0028 | memcpy( pNewAry + nSecPos, mpPointAry + nPos, nRest * sizeof( Point ) );
0029 | delete[] reinterpret_cast<char*>(mpPointAry);
0030 | if( mpFlagAry )
0031 | {
0032 | PolyFlags* pNewFlagAry = new PolyFlags[ nNewSize ];
0033 | memcpy( pNewFlagAry, mpFlagAry, nPos );
0034 | if( pInitPoly && pInitPoly->mpFlagAry )
0035 | memcpy( pNewFlagAry + nPos, pInitPoly->mpFlagAry, nSpace );
0036 | else
0037 | memset( pNewFlagAry + nPos, 0, nSpace );
0038 | memcpy( pNewFlagAry + nSecPos, mpFlagAry + nPos, nRest );
0039 | delete[] mpFlagAry;
0040 | mpFlagAry = pNewFlagAry;
0041 | }
0042 | mpPointAry = pNewAry;
0043 | mnPoints   = nNewSize;
0044 | }
0045 | }

