[xar_get_toc_data_values]

0001 | static int xar_get_toc_data_values(xmlTextReaderPtr reader, long *length, long *offset, long *size, int *encoding,
0002 | unsigned char ** a_cksum, int * a_hash, unsigned char ** e_cksum, int * e_hash)
0003 | {
0004 | const xmlChar *name;
0005 | int indata = 0, inea = 0;
0006 | int rc, gotoffset=0, gotlength=0, gotsize=0;
0007 | *a_cksum = NULL;
0008 | *a_hash = XAR_CKSUM_NONE;
0009 | *e_cksum = NULL;
0010 | *e_hash = XAR_CKSUM_NONE;
0011 | *encoding = CL_TYPE_ANY;
0012 | rc = xmlTextReaderRead(reader);
0013 | while (rc == 1) {
0014 | name = xmlTextReaderConstLocalName(reader);
0015 | if (indata || inea) {
0016 | if (xmlStrEqual(name, (const xmlChar *)"offset") && 
0017 | xmlTextReaderNodeType(reader) == XML_READER_TYPE_ELEMENT) {
0018 | if (CL_SUCCESS == xar_get_numeric_from_xml_element(reader, offset))
0019 | gotoffset=1;
0020 | } else if (xmlStrEqual(name, (const xmlChar *)"length") &&
0021 | xmlTextReaderNodeType(reader) == XML_READER_TYPE_ELEMENT) {
0022 | if (CL_SUCCESS == xar_get_numeric_from_xml_element(reader, length))
0023 | gotlength=1;
0024 | } else if (xmlStrEqual(name, (const xmlChar *)"size") &&
0025 | xmlTextReaderNodeType(reader) == XML_READER_TYPE_ELEMENT) {
0026 | if (CL_SUCCESS == xar_get_numeric_from_xml_element(reader, size))
0027 | gotsize=1;
0028 | } else if (xmlStrEqual(name, (const xmlChar *)"archived-checksum") &&
0029 | xmlTextReaderNodeType(reader) == XML_READER_TYPE_ELEMENT) {
0030 | cli_dbgmsg("cli_scanxar: <archived-checksum>:\n");
0031 | xar_get_checksum_values(reader, a_cksum, a_hash);
0032 | } else if ((xmlStrEqual(name, (const xmlChar *)"extracted-checksum") ||
0033 | xmlStrEqual(name, (const xmlChar *)"unarchived-checksum")) &&
0034 | xmlTextReaderNodeType(reader) == XML_READER_TYPE_ELEMENT) {
0035 | cli_dbgmsg("cli_scanxar: <extracted-checksum>:\n");
0036 | xar_get_checksum_values(reader, e_cksum, e_hash);
0037 | } else if (xmlStrEqual(name, (const xmlChar *)"encoding") &&
0038 | xmlTextReaderNodeType(reader) == XML_READER_TYPE_ELEMENT) {
0039 | xmlChar * style = xmlTextReaderGetAttribute(reader, (const xmlChar *)"style");
0040 | if (style == NULL) {
0041 | cli_dbgmsg("cli_scaxar: xmlTextReaderGetAttribute no style attribute "
0042 | "for encoding element\n");
0043 | *encoding = CL_TYPE_ANY;
0044 | } else if (xmlStrEqual(style, (const xmlChar *)"application/x-gzip")) {
0045 | cli_dbgmsg("cli_scanxar: encoding = application/x-gzip.\n");
0046 | *encoding = CL_TYPE_GZ; 
0047 | } else if (xmlStrEqual(style, (const xmlChar *)"application/octet-stream")) {
0048 | cli_dbgmsg("cli_scanxar: encoding = application/octet-stream.\n");
0049 | *encoding = CL_TYPE_ANY; 
0050 | } else if (xmlStrEqual(style, (const xmlChar *)"application/x-bzip2")) {
0051 | cli_dbgmsg("cli_scanxar: encoding = application/x-bzip2.\n");
0052 | *encoding = CL_TYPE_BZ;
0053 | } else if (xmlStrEqual(style, (const xmlChar *)"application/x-lzma")) {
0054 | cli_dbgmsg("cli_scanxar: encoding = application/x-lzma.\n");
0055 | *encoding = CL_TYPE_7Z;
0056 | } else if (xmlStrEqual(style, (const xmlChar *)"application/x-xz")) {
0057 | cli_dbgmsg("cli_scanxar: encoding = application/x-xz.\n");
0058 | *encoding = CL_TYPE_XZ;
0059 | } else {
0060 | cli_dbgmsg("cli_scaxar: unknown style value=%s for encoding element\n", style);
0061 | *encoding = CL_TYPE_ANY;
0062 | }
0063 | if (style != NULL)
0064 | xmlFree(style);
0065 | } else if (indata && xmlStrEqual(name, (const xmlChar *)"data") &&
0066 | xmlTextReaderNodeType(reader) == XML_READER_TYPE_END_ELEMENT) {
0067 | break;
0068 | } else if (inea && xmlStrEqual(name, (const xmlChar *)"ea") &&
0069 | xmlTextReaderNodeType(reader) == XML_READER_TYPE_END_ELEMENT) {
0070 | break;
0071 | }
0072 | } else {
0073 | if (xmlTextReaderNodeType(reader) == XML_READER_TYPE_ELEMENT) {
0074 | if (xmlStrEqual(name, (const xmlChar *)"data")) {
0075 | cli_dbgmsg("cli_scanxar: xmlTextReaderRead read <data>\n");
0076 | indata = 1;
0077 | } else if (xmlStrEqual(name, (const xmlChar *)"ea")) {
0078 | cli_dbgmsg("cli_scanxar: xmlTextReaderRead read <ea>\n");
0079 | inea = 1;
0080 | }
0081 | } else if ((xmlTextReaderNodeType(reader) == XML_READER_TYPE_END_ELEMENT) &&
0082 | xmlStrEqual(name, (const xmlChar *)"xar")) {
0083 | cli_dbgmsg("cli_scanxar: finished parsing xar TOC.\n");   
0084 | break;
0085 | }
0086 | }
0087 | rc = xmlTextReaderRead(reader);
0088 | }
0089 | if (gotoffset && gotlength && gotsize) {
0090 | rc = CL_SUCCESS;
0091 | }
0092 | else if (0 == gotoffset + gotlength + gotsize)
0093 | rc = CL_BREAK;
0094 | else
0095 | rc = CL_EFORMAT;
0096 | return rc;
0097 | }
